const ui={healthBar:document.querySelector('#healthBar'),healthNum:document.querySelector('#healthNum'),score:document.querySelector('#score'),streak:document.querySelector('#streak'),waveNum:document.querySelector('#waveNum'),waveHint:document.querySelector('#waveHint'),chargeWrap:document.querySelector('#chargeWrap'),chargeBar:document.querySelector('#chargeBar'),chargeLabel:document.querySelector('#chargeLabel'),toast:document.querySelector('#toast'),overlay:document.querySelector('#overlay'),hint:document.querySelector('#hint'),restart:document.querySelector('#restart')};

function makeEnemy(x,z){
 const g=new THREE.Group();g.position.set(x,0,z);scene.add(g);
 const body=new THREE.Mesh(new THREE.CapsuleGeometry(.37,.72,4,9),enemyMat);body.position.y=.9;body.castShadow=true;g.add(body);
 const head=new THREE.Mesh(new THREE.SphereGeometry(.27,12,10),mat(0xb87564,.83));head.position.y=1.65;head.castShadow=true;g.add(head);
 const hood=new THREE.Mesh(new THREE.ConeGeometry(.31,.3,7),enemyDark);hood.position.y=1.91;hood.castShadow=true;g.add(hood);
 const sash=new THREE.Mesh(new THREE.BoxGeometry(.78,.13,.12),goldMat);sash.position.set(0,1.08,.27);g.add(sash);
 const legs=[];for(let s of [-1,1]){const leg=new THREE.Mesh(new THREE.CapsuleGeometry(.14,.43,3,6),enemyDark);leg.position.set(s*.19,.34,0);leg.castShadow=true;g.add(leg);legs.push(leg)}
 const glow=new THREE.Mesh(new THREE.SphereGeometry(.72,12,10),new THREE.MeshBasicMaterial({color:0xff536c,transparent:true,opacity:.08,wireframe:true,depthWrite:false}));glow.position.y=1;g.add(glow);
 const e={group:g,body,legs,glow,hp:1,stun:0,knock:new THREE.Vector3(),attack:Math.random()*.8,phase:Math.random()*6.28,alive:true};enemies.push(e);return e;
}
function spawnWave(){let count=Math.min(3+state.wave*2,15);for(let i=0;i<count;i++){let a=Math.PI*2*(i/count)+Math.random()*.24,r=9.7+Math.random()*1.8;makeEnemy(Math.sin(a)*r,Math.cos(a)*r)}state.waveWait=0;state.streak=0;ui.waveNum.textContent=`WAVE ${String(state.wave).padStart(2,'0')}`;ui.waveHint.textContent=`${count} OPPONENTS · HOLD YOUR GROUND`}
function makeBurst(pos,color,count=14,power=3){for(let i=0;i<count;i++){const m=new THREE.Mesh(new THREE.IcosahedronGeometry(.035+Math.random()*.055,0),new THREE.MeshBasicMaterial({color,transparent:true,opacity:1}));m.position.copy(pos);scene.add(m);const d=new THREE.Vector3(Math.random()-.5,Math.random()*.9,Math.random()-.5).normalize().multiplyScalar(power*(.35+Math.random()));particles.push({mesh:m,vel:d,life:.45+Math.random()*.55,max:1})}}
function makeRing(x,z,scale,color){const mesh=new THREE.Mesh(new THREE.TorusGeometry(1,.055,8,64),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.85,depthWrite:false}));mesh.rotation.x=Math.PI/2;mesh.position.set(x,.12,z);mesh.scale.setScalar(scale);scene.add(mesh);rings.push({mesh,life:.52,max:.52})}
function showToast(text){ui.toast.textContent=text;ui.toast.classList.add('show');state.toastTimer=1.05}
function blast(){if(!state.running||state.gameOver)return;let strength=.55+state.charge*.95;state.charging=false;state.charge=0;ui.chargeWrap.classList.remove('show');const radius=3.4+strength*4.6;const power=7+strength*11;makeRing(hero.position.x,hero.position.z,.45,0x92f6ff);makeBurst(new THREE.Vector3(hero.position.x,1.05,hero.position.z),0x9af5ff,32,5+strength*4);
 const flash=new THREE.PointLight(0x69eaff,25+strength*40,10+strength*12);flash.position.set(hero.position.x,1.3,hero.position.z);scene.add(flash);setTimeout(()=>scene.remove(flash),190);
 let hits=0;for(const e of enemies){if(!e.alive)continue;const dx=e.group.position.x-hero.position.x,dz=e.group.position.z-hero.position.z,d=Math.hypot(dx,dz);if(d<radius){hits++;const dir=new THREE.Vector3(dx,0,dz).normalize();if(!dir.length())dir.set(Math.random()-.5,0,Math.random()-.5).normalize();e.knock.addScaledVector(dir,power*(.45+(1-d/radius)*.9));e.knock.y+=1.4+strength*1.7;e.stun=Math.max(e.stun,.5+strength*.7);e.hp-=strength>.92?2:1;makeBurst(new THREE.Vector3(e.group.position.x,.9,e.group.position.z),0xffbd70,8,2.7);if(e.hp<=0){e.alive=false;state.score++;state.streak++;state.best=Math.max(state.best,state.streak);ui.score.textContent=String(state.score).padStart(2,'0');ui.streak.textContent=`×${state.best}`;makeBurst(new THREE.Vector3(e.group.position.x,.7,e.group.position.z),0xff7181,18,4);setTimeout(()=>scene.remove(e.group),500)}}}
 showToast(hits===0?'FEEL THE FORCE':hits>3?'OVERWHELMING WILL':hits>0?'AURA BREAK!':'UNBREAKABLE');if(hits>0){state.streak=Math.max(state.streak,hits);ui.streak.textContent=`×${state.best}`}
}
function damage(){if(state.damageCooldown>0||state.gameOver)return;state.damageCooldown=1.05;state.health=Math.max(0,state.health-12);state.streak=0;hero.children.forEach(c=>{if(c.material===heroMat)c.material=mat(0xff6677,.55)});setTimeout(()=>hero.children.forEach(c=>{if(c.material?.color?.getHex()===0xff6677)c.material=heroMat}),180);ui.healthBar.style.width=`${state.health}%`;ui.healthNum.textContent=`${state.health}%`;makeBurst(new THREE.Vector3(hero.position.x,.9,hero.position.z),0xff596c,9,2);if(state.health<=0)endGame()}
function endGame(){state.gameOver=true;state.running=false;ui.overlay.classList.remove('hidden');ui.restart.classList.remove('show');document.querySelector('.eyebrow').textContent='THE ARENA REMEMBERS';document.querySelector('.panel h1').innerHTML='WILL<br><em>UNBROKEN?</em>';document.querySelector('.panel p').innerHTML=`You cleared <b>${state.wave-1}</b> waves and sent <b>${state.score}</b> foes flying. Every legend starts with one more stand.`;document.querySelector('.controls').style.display='none';document.querySelector('#start').textContent='RISE AGAIN';document.querySelector('.footer').textContent=`BEST STREAK ×${state.best}  ·  AURA UP. FEAR DOWN.`}
function reset(){for(const e of enemies)scene.remove(e.group);enemies.length=0;for(const p of particles)scene.remove(p.mesh);particles.length=0;for(const r of rings)scene.remove(r.mesh);rings.length=0;hero.position.set(0,0,0);state.health=100;state.score=0;state.streak=0;state.best=0;state.wave=1;state.waveWait=0;state.charge=0;state.charging=false;state.gameOver=false;state.damageCooldown=0;ui.healthBar.style.width='100%';ui.healthNum.textContent='100%';ui.score.textContent='00';ui.streak.textContent='×0';ui.waveNum.textContent='WAVE 01';ui.waveHint.textContent='THEY\'RE CLOSING IN';document.querySelector('.controls').style.display='grid';document.querySelector('.eyebrow').textContent='A TEST OF UNWAVERING WILL';document.querySelector('.panel h1').innerHTML='THE AURA<br><em>BREAKER</em>';document.querySelector('.panel p').textContent='Stand your ground. Gather your will. Send the whole pack flying with a single shockwave.';document.querySelector('#start').textContent='ENTER THE ARENA';document.querySelector('.footer').textContent='AURA UP. FEAR DOWN.';spawnWave()}
function startGame(){reset();state.running=true;ui.overlay.classList.add('hidden');ui.restart.classList.add('show');state.elapsed=0}

