function startGame(){reset();state.running=true;ui.overlay.classList.add('hidden');ui.restart.classList.add('show');state.elapsed=0}

const keys=new Set();let pointerMove=null;
window.addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();keys.add(e.code);if(e.code==='Space'&&!e.repeat&&state.running){state.charging=true;ui.chargeWrap.classList.add('show')}});
window.addEventListener('keyup',e=>{keys.delete(e.code);if(e.code==='Space'&&state.charging)blast()});
